import pandas as pd

def summarize(frame):
    required = {"category", "units", "price"}
    missing = required - set(frame.columns)
    if missing: raise ValueError(f"Missing columns: {sorted(missing)}")
    work = frame.assign(revenue=frame["units"] * frame["price"])
    return work.groupby("category", as_index=False)["revenue"].sum()

example = pd.DataFrame({"category": ["A", "A"], "units": [2, 3], "price": [10, 5]})
print(summarize(example).to_dict("records"))
